CREATE TABLE ai_drafts (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,kind TEXT NOT NULL,input_snapshot TEXT NOT NULL,output_text TEXT NOT NULL,model TEXT NOT NULL,provider_response_id TEXT,status TEXT NOT NULL DEFAULT 'draft',reviewed_by TEXT,reviewed_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_ai_drafts_resource ON ai_drafts(agency_id,resource_type,resource_id,kind,created_at);
CREATE INDEX idx_ai_drafts_review ON ai_drafts(agency_id,status,created_at);
CREATE TABLE api_credentials (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),name TEXT NOT NULL,key_prefix TEXT NOT NULL,key_hash TEXT NOT NULL,scopes TEXT NOT NULL,expires_at TEXT,last_used_at TEXT,revoked_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_api_credentials_hash ON api_credentials(key_hash);
CREATE INDEX idx_api_credentials_agency ON api_credentials(agency_id,revoked_at,expires_at);
CREATE TABLE api_request_events (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),credential_id TEXT NOT NULL REFERENCES api_credentials(id),route TEXT NOT NULL,method TEXT NOT NULL,status_code INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_api_request_rate ON api_request_events(credential_id,created_at);
CREATE INDEX idx_api_request_agency ON api_request_events(agency_id,created_at);
CREATE TABLE api_idempotency_keys (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),credential_id TEXT NOT NULL REFERENCES api_credentials(id),idempotency_key TEXT NOT NULL,route TEXT NOT NULL,response_status INTEGER NOT NULL,response_body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_api_idempotency_unique ON api_idempotency_keys(credential_id,route,idempotency_key);
CREATE TABLE integration_connections (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),kind TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',configuration TEXT NOT NULL DEFAULT '{}',approved_by TEXT,approved_at TEXT,last_sync_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_integration_connection ON integration_connections(agency_id,kind,provider);
CREATE TABLE integration_sync_runs (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),connection_id TEXT NOT NULL REFERENCES integration_connections(id),direction TEXT NOT NULL,resource_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'running',records_read INTEGER NOT NULL DEFAULT 0,records_written INTEGER NOT NULL DEFAULT 0,failure_reason TEXT,idempotency_key TEXT NOT NULL,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE UNIQUE INDEX idx_integration_sync_idempotency ON integration_sync_runs(connection_id,idempotency_key);
CREATE INDEX idx_integration_sync_agency ON integration_sync_runs(agency_id,status,started_at);
CREATE TABLE developments (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),name TEXT NOT NULL,developer_contact_id TEXT REFERENCES contacts(id),property_id TEXT REFERENCES properties(id),location TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'planning',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_developments_agency_status ON developments(agency_id,status,created_at);
CREATE TABLE development_units (id TEXT PRIMARY KEY NOT NULL,agency_id TEXT NOT NULL REFERENCES agencies(id),development_id TEXT NOT NULL REFERENCES developments(id),property_id TEXT REFERENCES properties(id),unit_reference TEXT NOT NULL,unit_type TEXT NOT NULL,price_minor INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL DEFAULT 'available',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_development_unit_reference ON development_units(agency_id,development_id,unit_reference);
CREATE INDEX idx_development_units_status ON development_units(agency_id,development_id,status);
CREATE TABLE enterprise_branding (agency_id TEXT PRIMARY KEY NOT NULL REFERENCES agencies(id),portal_name TEXT NOT NULL DEFAULT '',logo_media_id TEXT REFERENCES media_assets(id),favicon_media_id TEXT REFERENCES media_assets(id),primary_domain TEXT,hide_parent_brand INTEGER NOT NULL DEFAULT 0,email_from_name TEXT NOT NULL DEFAULT '',updated_by TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
PRAGMA optimize;
